#!/usr/bin/env python3
"""Install the reviewed counter1 guard and saved-inspector pair; no execution."""
import base64, datetime, gzip, hashlib, io, json, os, stat
from pathlib import Path
BASE = Path('/data/local/tmp/pixel-gpu-transfer-sxtv33sh')
ROOTS = (Path('/data/local/tmp/pixel-boot-checks-counter1'), Path('/data/local/tmp/pixel-saved-checks-counter1'))
RECEIPT = BASE / 'counter1-guard-inspector-install.json'
FILES = [{'path': '/data/local/tmp/pixel-boot-checks-counter1/firstboot/guard_ios26_firstboot.py', 'bytes': 25686, 'sha256': 'ea40638312d6ac41607806ecb03c148fbd0677df6ab01480e13fd40536869674', 'payload': ''}, {'path': '/data/local/tmp/pixel-saved-checks-counter1/inspect_ios26_firstboot.py', 'bytes': 26030, 'sha256': '2b127ecda390b199287358cdad7e6e7774f5b787148aea524e7b0247a2640cf3', 'payload': ''}, {'path': '/data/local/tmp/pixel-saved-checks-counter1/inspect_ios26_firstboot_guest.py', 'bytes': 16829, 'sha256': 'ada26de8ababb11bb4af20e558708545eb64fd516481359fd5d0ccf6a7cbae2b', 'payload': ''}]


def install():
    if os.geteuid() != 0 or BASE.resolve(strict=True) != BASE: raise ValueError('canonical root transfer directory required')
    if any(path.parent.resolve(strict=True) != path.parent for path in ROOTS): raise ValueError('noncanonical source parents')
    if any(os.path.lexists(path) for path in (*ROOTS, RECEIPT)): raise FileExistsError('source directory or receipt exists; preserve it')
    decoded = []
    for row in FILES:
        with gzip.GzipFile(fileobj=io.BytesIO(base64.b64decode(row['payload'], validate=True)), mode='rb') as stream:
            body = stream.read(row['bytes'] + 1)
        if len(body) != row['bytes'] or hashlib.sha256(body).hexdigest() != row['sha256']: raise ValueError('embedded source differs')
        decoded.append((row, body))
    receipt_fd = os.open(RECEIPT, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    try:
        for path in ROOTS: path.mkdir(mode=0o700)
        (ROOTS[0] / 'firstboot').mkdir(mode=0o700)
        installed = {}
        for row, body in decoded:
            path = Path(row['path'])
            with os.fdopen(os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o644), 'wb') as output:
                output.write(body); output.flush(); os.fchmod(output.fileno(), 0o644); os.fsync(output.fileno())
            with os.fdopen(os.open(path, os.O_RDONLY | os.O_NOFOLLOW), 'rb') as source:
                info = os.fstat(source.fileno()); copied = source.read(row['bytes'] + 1)
            if (not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_uid != 0 or
                    stat.S_IMODE(info.st_mode) != 0o644 or info.st_size != row['bytes'] or copied != body):
                raise ValueError('installed source readback or identity differs')
            installed[str(path)] = {'bytes': len(copied), 'sha256': hashlib.sha256(copied).hexdigest()}
        receipt = {'schema': 1, 'kind': 'counter1_guard_and_saved_inspector_source_install',
                   'installed_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(),
                   'status': 'VERIFIED', 'files': installed, 'execution_started': False,
                   'old_source_directories_changed': False, 'frozen_runner_changed': False}
        with os.fdopen(receipt_fd, 'w', closefd=False) as output:
            json.dump(receipt, output, indent=2); output.write('\n'); output.flush(); os.fsync(output.fileno())
        for path in (ROOTS[0] / 'firstboot', *ROOTS, ROOTS[0].parent, BASE):
            directory = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
            try: os.fsync(directory)
            finally: os.close(directory)
        return receipt
    finally: os.close(receipt_fd)


if __name__ == '__main__':
    value = install()
    print('COUNTER1 SOURCES INSTALLED', value['installed_utc'])
    for path, row in value['files'].items():
        print('source=' + path + ' bytes=' + str(row['bytes']))
        print('sha_a=' + row['sha256'][:32]); print('sha_b=' + row['sha256'][32:])
    digest = hashlib.sha256(RECEIPT.read_bytes()).hexdigest()
    print('receipt=' + str(RECEIPT)); print('receipt_sha_a=' + digest[:32]); print('receipt_sha_b=' + digest[32:])
    print('execution_started=false old_sources_changed=false frozen_runner_changed=false', flush=True)
